 const tools=dialog('readerTools','阅读工具',`<section><h4>书内搜索</h4><form id="bookSearchForm"><div class="feature-row"><input id="bookSearch" type="search" placeholder="输入要找的词句" maxlength="120"><button>搜索</button></div><label class="feature-hint"><input id="searchUnread" type="checkbox"> 搜索全文（结果可能包含未读情节）</label></form><p id="searchInfo" class="feature-hint"></p><div id="searchResults" class="search-results"></div></section><section><div class="feature-row"><h4>书签</h4><button id="addBookmark">收藏当前位置</button></div><div id="bookmarkList"></div></section><section><h4>书籍管理</h4><div class="feature-row"><label>阅读状态<select id="bookState"><option value="unread">未读</option><option value="reading">在读</option><option value="finished">读完</option></select></label><label>分组<input id="bookGroup" maxlength="24" placeholder="例如：小说 / 专业课"></label><label><input id="bookFavorite" type="checkbox"> 收藏</label><button id="saveBookInfo">保存</button></div></section><section><h4>听书</h4><p class="feature-hint">从当前附近朗读，单次最多12000字。使用设备本地语音；音色取决于系统安装情况。</p><div class="feature-row"><label>音色<select id="ttsVoice"></select></label><label>语速<select id="ttsRate"><option value="0.8">0.8×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option></select></label><label>音调<input id="ttsPitch" type="range" min="0.5" max="1.5" step="0.1" value="1"></label><label>定时停止<select id="ttsSleep"><option value="0">不定时</option><option value="10">10分钟</option><option value="20">20分钟</option><option value="30">30分钟</option></select></label></div><div class="feature-row"><button id="ttsStart">开始朗读</button><button id="ttsStop">停止</button><span id="ttsStatus" class="feature-hint"></span></div></section><section><h4>阅读助手</h4><p class="feature-hint">沿用已读范围和你的 API 配置。不会为这些任务额外发送未读章节。</p><div class="feature-row"><button data-ai="请把已读内容总结成清晰的要点，标明不确定之处。">总结已读</button><button data-ai="请分析已读内容中的人物观点、论证或叙事方式，区分原文与推测。">观点分析</button><button id="generateMindMap">思维导图</button><button data-ai="请将最近一段已读内容翻译成英文，逐段列出原文与译文；若原文是英文则翻译成中文。">对照翻译</button></div></section>`);
 const extras=document.createElement('section');extras.innerHTML=`<h4>文字处理</h4><p class="feature-hint">简繁转换在本地完成，生成新的TXT副本，原书与笔记保留。</p><div class="feature-row"><button id="toSimplified">另存简体副本</button><button id="toTraditional">另存繁体副本</button></div><div class="feature-row dictionary-row"><input id="dictionaryWord" maxlength="120" placeholder="输入想查的词句"><button id="lookupWord">AI词典</button></div><hr><h4>全文对照翻译</h4><p class="feature-hint">逐段发送整本书到你配置的AI服务，可能产生API费用；结果另存为原文/译文对照TXT。可取消，重开后继续上次分段。</p><label class="feature-hint"><input id="translateUnread" type="checkbox"> 我选择翻译全书，包含尚未阅读的文字</label><div class="feature-row"><select id="translationLanguage"><option value="中文">译为中文</option><option value="英文">译为英文</option><option value="日文">译为日文</option></select><button id="translateBook">开始 / 继续翻译</button><button id="cancelTranslation">取消</button></div><p id="translationStatus" class="feature-hint" role="status"></p>`;tools.append(extras);const mapSection=document.createElement('section');mapSection.innerHTML='<h4>已读内容思维导图</h4><div id="mindMapResult" class="mind-map-tree"></div>';tools.insertBefore(mapSection,extras);
 let translationController=null;const cancelTranslation=()=>translationController?.abort();$('cancelTranslation').onclick=cancelTranslation;tools.addEventListener('close',cancelTranslation);
